def task_func(process_name):
    import subprocess, os
    try:
        # Call pgrep with the process name to get matching process IDs.
        out = subprocess.check_output(["pgrep", process_name])
    except subprocess.CalledProcessError:
        # If pgrep fails (e.g. no process with that name), return 0.
        return 0

    # Decode the bytes output to a string and split by lines.
    pids = out.decode().splitlines()

    # Kill each process with signal 15 (SIGTERM).
    for pid in pids:
        os.kill(int(pid), 15)

    return len(pids)


